# Observer Pattern
class EventManager:
    def __init__(self):
        self._listeners = {}

    def subscribe(self, event, callback):
        self._listeners.setdefault(event, []).append(callback)

    def emit(self, event, data):
        for callback in self._listeners.get(event, []):
            callback(data)

