    cdef int b = 1
    cdef int i
    for i in range(n):
        a, b = b, a + b
    return a

def primes(int limit):
    cdef int i, j
    cdef bint is_prime
    result = []
    for i in range(2, limit + 1):
        is_prime = True
        for j in range(2, int(i ** 0.5) + 1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            result.append(i)
    return result

